/* Fact Probe Explorer panels for embedding: generated by scripts/c01/build_explorer.py --embed-out.
   Mount points are elements with [data-fx]. The data (data.json, next to this file) and d3 load when a panel
   comes near the viewport; until then each panel shows its static frame. */
window.__fxBoot = function () {
(function () {
"use strict";
// an embedding page (build_explorer.py --embed-out) supplies the data itself and mounts only some chapters
const D = window.__FX_DATA__ || JSON.parse(document.getElementById("explorer-data").textContent);
const on = s => !!document.querySelector(s);
const NUM = D.numbers;
const $ = (s, r) => (r || document).querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const f2 = v => (v == null || !isFinite(v)) ? "n/a" : v.toFixed(2);
const f3 = v => (v == null || !isFinite(v)) ? "n/a" : v.toFixed(3);
const sgn = v => (v >= 0 ? "+" : "−") + Math.abs(v).toFixed(3);
const pct = (v, d) => (100 * v).toFixed(d || 0) + "%";
const fmtInt = n => n.toLocaleString("en-US");
const hasD3 = typeof d3 !== "undefined";

/* ------------------------------------------------------------ claims and metrics */
const claims = [];
D.bios.forEach((b, bi) => b.facts.forEach((f, fi) => claims.push(Object.assign({ bi, fi, pop: Math.log10(1 + b.views) }, f))));
const SIG = {
  probe:    { label: "Probe", key: "p", color: "var(--c-probe)" },
  ptrue:    { label: "P(True)", key: "q", color: "var(--c-ptrue)" },
  verifier: { label: "Llama-as-verifier", key: "v", color: "var(--c-verifier)" },
  stack:    { label: "Probe + P(True)", key: "k", color: "var(--c-stack)", dash: true, explor: true },
  pop:      { label: "Subject popularity", key: "pop", color: "var(--c-pop)", dash: true }
};

function auroc(s, y) {
  const idx = s.map((_, i) => i).sort((a, b) => s[a] - s[b]);
  let rs = 0, np = 0, nn = 0, i = 0;
  while (i < idx.length) {
    let j = i;
    while (j + 1 < idx.length && s[idx[j + 1]] === s[idx[i]]) j++;
    const r = (i + j) / 2 + 1;
    for (let k = i; k <= j; k++) { if (y[idx[k]] === 1) { rs += r; np++; } else nn++; }
    i = j + 1;
  }
  return (np && nn) ? (rs - np * (np + 1) / 2) / (np * nn) : NaN;
}
// claims sorted most-doubted first, grouped into tie blocks
function tieBlocks(items, key) {
  const s = items.slice().sort((a, b) => a[key] - b[key]);
  const blocks = [];
  for (const c of s) {
    const last = blocks[blocks.length - 1];
    if (last && last.v === c[key]) last.items.push(c); else blocks.push({ v: c[key], items: [c] });
  }
  return blocks;
}
// flag up to k claims, never splitting a tie block; also return the block that did not fit
function flagged(items, key, k) {
  const out = new Set();
  let stop = null;
  for (const b of tieBlocks(items, key)) {
    if (out.size + b.items.length > k) { stop = b; break; }
    b.items.forEach(c => out.add(c));
  }
  out.stop = stop;
  return out;
}
function gainCurve(items, key) {
  const nF = items.filter(c => c.y === 0).length, n = items.length;
  const pts = [[0, 0]];
  let x = 0, yv = 0;
  for (const b of tieBlocks(items, key)) {
    x += b.items.length / n; yv += b.items.filter(c => c.y === 0).length / nF;
    pts.push([x, yv]);
  }
  return pts;
}
function interp(pts, x) {
  for (let i = 1; i < pts.length; i++) if (pts[i][0] >= x) {
    const [x0, y0] = pts[i - 1], [x1, y1] = pts[i];
    return x1 === x0 ? y1 : y0 + (y1 - y0) * (x - x0) / (x1 - x0);
  }
  return 1;
}
const BIO_AUC = D.bios.map(b => {
  const y = b.facts.map(f => f.y);
  return { p: auroc(b.facts.map(f => f.p), y), q: auroc(b.facts.map(f => f.q), y), v: auroc(b.facts.map(f => f.v), y), k: auroc(b.facts.map(f => f.k), y),
           nF: y.filter(v => v === 0).length, n: y.length };
});

/* ------------------------------------------------------------ chart helpers */
function frame(el, h, m) {
  el.innerHTML = "";
  const w = Math.max(280, el.clientWidth || 600);
  const svg = d3.select(el).append("svg").attr("viewBox", `0 0 ${w} ${h}`).attr("width", w).attr("height", h);
  const g = svg.append("g").attr("transform", `translate(${m.l},${m.t})`);
  return { svg, g, w, h, iw: w - m.l - m.r, ih: h - m.t - m.b };
}
function tipFor(el) {
  let t = el.querySelector(".tip");
  if (!t) { t = document.createElement("div"); t.className = "tip"; t.hidden = true; el.appendChild(t); }
  return {
    show(html, x, y) { t.innerHTML = html; t.hidden = false; const W = el.clientWidth; const tw = t.offsetWidth; t.style.left = Math.min(Math.max(0, x + 12), W - tw) + "px"; t.style.top = (y + 12) + "px"; },
    hide() { t.hidden = true; }
  };
}
// redraw a chart when its own box changes width (pane resizes, layout settles, fonts load)
function watch(el, fn) {
  let last = el.clientWidth, t;
  const ro = new ResizeObserver(() => { const w = el.clientWidth; if (Math.abs(w - last) < 2) return; last = w; clearTimeout(t); t = setTimeout(() => { try { fn(); } catch (e) { console.error(e); } }, 80); });
  ro.observe(el);
}

/* ------------------------------------------------------------ scoreboard */
function drawScoreboard() {
  const el = $("#scoreboard");
  const rows = [
    { lab: "Llama-as-verifier (stated probability)", n: NUM.verifier_auroc, c: "var(--c-verifier)" },
    { lab: "P(True) (token probability)", n: NUM.ptrue_auroc, c: "var(--c-ptrue)" },
    { lab: "Probe on layer-19 activations", n: NUM.probe_auroc, c: "var(--c-probe)", strong: true },
    { lab: "Probe + P(True), exploratory", n: NUM.stack_test_auroc, c: "var(--c-stack)", dash: true }
  ];
  const narrow = el.clientWidth < 620;
  const m = { l: narrow ? 16 : 270, r: narrow ? 46 : 54, t: 26, b: 30 };
  const rowH = narrow ? 44 : 30;
  const F = frame(el, m.t + m.b + rows.length * rowH, m);
  const x = d3.scaleLinear().domain([0.5, 1]).range([0, F.iw]);
  F.g.append("g").attr("transform", `translate(0,${rows.length * rowH})`).attr("class", "axis").call(d3.axisBottom(x).ticks(5).tickFormat(d3.format(".1f")));
  [0.5, 0.6, 0.7, 0.8, 0.9, 1].forEach(v => F.g.append("line").attr("class", "gridline").attr("x1", x(v)).attr("x2", x(v)).attr("y1", -8).attr("y2", rows.length * rowH));
  F.g.append("text").attr("class", "lbl").attr("x", x(0.5)).attr("y", -12).text("coin flip");
  F.g.append("text").attr("class", "lbl").attr("x", x(1)).attr("y", -12).attr("text-anchor", "end").text("perfect");
  rows.forEach((r, i) => {
    const yy = i * rowH + (narrow ? 30 : rowH / 2);
    if (narrow) F.g.append("text").attr("class", r.strong ? "lbl-strong" : "lbl-ink").attr("x", 0).attr("y", yy - 13).text(r.lab);
    else F.g.append("text").attr("class", r.strong ? "lbl-strong" : "lbl-ink").attr("x", -14).attr("y", yy + 4).attr("text-anchor", "end").text(r.lab);
    F.g.append("line").attr("x1", x(r.n.lo)).attr("x2", x(r.n.hi)).attr("y1", yy).attr("y2", yy).style("stroke", r.c).attr("stroke-width", 3).attr("stroke-linecap", "round").attr("stroke-dasharray", r.dash ? "4 3" : null).attr("opacity", 0.55);
    F.g.append("circle").attr("cx", x(r.n.value)).attr("cy", yy).attr("r", r.strong ? 7 : 5.5).style("fill", r.c).style("stroke", "var(--panel)").attr("stroke-width", 2);
    F.g.append("text").attr("class", r.strong ? "lbl-strong" : "lbl-ink").attr("x", x(r.n.hi) + 8).attr("y", yy + 4).text(f3(r.n.value));
  });
}

/* ------------------------------------------------------------ reader */
const state = { bio: D.default_bio, sig: "probe", pctFlag: Math.round(100 * NUM.n_test_false.value / NUM.n_test_claims.value), sel: null, sort: null };
const READER_SIGS = ["probe", "ptrue", "verifier", "stack"];
function setupReader() {
  const sel = $("#bioSel");
  const order = D.bios.map((b, i) => i);
  sel.innerHTML = order.map(i => `<option value="${i}">${esc(D.bios[i].name)}</option>`).join("");
  sel.value = state.bio;
  sel.addEventListener("change", () => { state.bio = +sel.value; state.sel = null; renderReader(); });
  $("#bioPrev").addEventListener("click", () => { state.bio = (state.bio + D.bios.length - 1) % D.bios.length; sel.value = state.bio; state.sel = null; renderReader(); });
  $("#bioNext").addEventListener("click", () => { state.bio = (state.bio + 1) % D.bios.length; sel.value = state.bio; state.sel = null; renderReader(); });
  const seg = $("#sigSeg");
  seg.innerHTML = READER_SIGS.map(k => `<button data-k="${k}" aria-pressed="${k === state.sig}"><span class="swatch" style="background:${SIG[k].color}"></span>${SIG[k].label}${SIG[k].explor ? "*" : ""}</button>`).join("");
  seg.addEventListener("click", e => { const b = e.target.closest("button"); if (!b) return; state.sig = b.dataset.k; seg.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b)); renderReader(); if (hasD3 && on("#gainChart")) drawGain(); });
  const r = $("#flagPct");
  r.value = state.pctFlag;
  r.addEventListener("input", () => { state.pctFlag = +r.value; r.setAttribute("aria-valuetext", state.pctFlag + "% of claims flagged"); renderReader(); if (hasD3 && on("#gainChart")) drawGain(); });
  const def = D.bios[D.default_bio].name;
  $("#defaultNote").textContent = `The reader opens on ${def}: of the biographies with at least eight correct and eight incorrect claims, it shows the widest gap between the probe and Llama-as-verifier. The strip below covers all ${D.bios.length}. * Probe + P(True) is exploratory.`;
}
function renderReader() {
  const b = D.bios[state.bio], key = SIG[state.sig].key;
  const k = Math.round(state.pctFlag / 100 * claims.length);
  const fl = flagged(claims, key, k);
  const mine = claims.filter(c => c.bi === state.bio);
  const isF = c => fl.has(c);
  $("#flagPctOut").textContent = state.pctFlag + "%";
  // summary
  const nF = mine.filter(c => c.y === 0).length, mineFl = mine.filter(isF), hit = mineFl.filter(c => c.y === 0).length;
  const allHit = [...fl].filter(c => c.y === 0).length, nFalseAll = claims.filter(c => c.y === 0).length;
  let note = "";
  if (fl.size < k && fl.stop) {
    const st = fl.stop, nTie = st.items.length;
    note = state.sig === "verifier" && st.v === 1
      ? ` Llama-as-verifier can flag only ${fl.size} claims: it gives the other ${fmtInt(nTie)} exactly 1.0.`
      : ` Ties keep the count at ${fl.size} rather than ${k}: the next ${fmtInt(nTie)} claims share one score (${state.sig === "verifier" ? st.v.toFixed(2) : st.v.toFixed(3)}) and cannot be split.`;
  }
  $("#readerSummary").innerHTML = `<b>${SIG[state.sig].label}</b> flags the ${state.pctFlag}% of all test claims it trusts least (${fl.size} of ${claims.length}). In this biography that marks <b>${mineFl.length}</b> of ${mine.length} claims, <b>${hit}</b> of them among its ${nF} incorrect ones. Across all ${D.bios.length} biographies it catches <b>${allHit} of ${nFalseAll}</b> incorrect claims (${pct(allHit / nFalseAll)}).${note}`;
  // header
  $("#bioName").textContent = b.name;
  $("#bioMeta").innerHTML = `<span><b>${mine.length}</b> claims</span><span><b>${nF}</b> incorrect</span><span>~<b>${fmtInt(b.views)}</b> Wikipedia views a month</span>`;
  // text
  const bySent = new Map();
  mine.forEach(c => { if (!bySent.has(c.s)) bySent.set(c.s, []); bySent.get(c.s).push(c); });
  let html = "", pos = 0;
  b.sents.forEach(([si, cs, ce]) => {
    if (cs > pos) html += esc(b.text.slice(pos, cs));
    const cl = bySent.get(si) || [];
    const frac = cl.length ? cl.filter(isF).length / cl.length : 0;
    const nWrong = cl.filter(c => c.y === 0).length;
    html += `<span class="sent${nWrong ? " has-false" : ""}${state.sel === si ? " sel" : ""}" data-s="${si}" style="--f:${Math.round(frac * 48)}%" tabindex="0" role="button" aria-pressed="${state.sel === si}">${esc(b.text.slice(cs, ce))}${nWrong ? `<sup aria-hidden="true">✗${nWrong}</sup>` : ""}<span class="sr-only"> (${cl.length} claims, ${cl.filter(isF).length} flagged, ${nWrong} incorrect)</span></span>`;
    pos = ce;
  });
  if (pos < b.text.length) html += esc(b.text.slice(pos));
  const tx = $("#bioText");
  tx.innerHTML = html;
  tx.onclick = e => { const s = e.target.closest(".sent"); if (!s) return; const si = +s.dataset.s; state.sel = state.sel === si ? null : si; renderReader(); scrollFactsTo(si); const again = $(`#bioText .sent[data-s="${si}"]`); if (again) again.focus({ preventScroll: true }); };
  tx.onkeydown = e => { if ((e.key === "Enter" || e.key === " ") && e.target.classList.contains("sent")) { e.preventDefault(); e.target.click(); } };
  // within-biography stats
  const A = BIO_AUC[state.bio];
  $("#bioStats").innerHTML = [["Probe", A.p, "var(--c-probe)"], ["P(True)", A.q, "var(--c-ptrue)"], ["Llama-as-verifier", A.v, "var(--c-verifier)"], ["Probe + P(True)*", A.k, "var(--c-stack)"]]
    .map(([l, v, c]) => `<div class="stat"><span class="k"><span class="swatch" style="background:${c}"></span> ${l}</span><span class="v">${f2(v)}</span></div>`).join("") +
    `<p class="caption" style="flex-basis:100%">Within-biography AUROC for this biography alone${A.nF === A.n ? ": undefined, because every claim here is incorrect" : A.nF === 0 ? ": undefined, because every claim here is correct" : A.nF < 5 ? `, from only ${A.nF} incorrect claims` : ""}.</p>`;
  // facts table
  const cols = [["#", c => c.s + 1, "s"], ["Claim", null, null], ["Supported?", c => c.y, "y"], ["Probe", c => c.p, "p"], ["P(True)", c => c.q, "q"], ["Verifier", c => c.v, "v"], ["Flag", c => isF(c) ? 1 : 0, "f"]];
  let rows = mine.slice();
  if (state.sort) { const [kk, dir] = state.sort; const col = cols.find(c => c[2] === kk); rows.sort((a, bb) => dir * (col[1](a) - col[1](bb)) || (a.s - bb.s) || (a.fi - bb.fi)); }
  const bar = v => `<span class="cellbar"><b style="width:${Math.round(v * 100)}%"></b></span>`;
  const sortState = kk => state.sort && state.sort[0] === kk ? (state.sort[1] > 0 ? "ascending" : "descending") : "none";
  $("#factTable").innerHTML = `<thead><tr>${cols.map(c => c[2] ? `<th data-k="${c[2]}" scope="col" aria-sort="${sortState(c[2])}"><button type="button">${c[0]}${sortState(c[2]) === "ascending" ? " ↑" : sortState(c[2]) === "descending" ? " ↓" : ""}</button></th>` : `<th scope="col">${c[0]}</th>`).join("")}</tr></thead><tbody>` +
    rows.map(c => `<tr class="${isF(c) ? "flagged" : ""}${state.sel === c.s ? " insel" : ""}" data-s="${c.s}"><td class="n">${c.s + 1}</td><td>${esc(c.t)}</td>` +
      `<td class="lab">${c.y ? '<span class="lab-t">✓ yes</span>' : '<span class="lab-f">✗ no</span>'}</td>` +
      `<td class="n">${c.p.toFixed(2)}${bar(c.p)}</td><td class="n">${c.q.toFixed(2)}${bar(c.q)}</td><td class="n">${c.v.toFixed(2)}${bar(c.v)}</td>` +
      `<td class="n flagmark">${isF(c) ? (c.y ? "⚑ false alarm" : "⚑ caught") : (c.y ? "" : "missed")}</td></tr>`).join("") + "</tbody>";
  $("#factTable thead").onclick = e => { const th = e.target.closest("th[data-k]"); if (!th) return; const kk = th.dataset.k; state.sort = state.sort && state.sort[0] === kk ? (state.sort[1] > 0 ? [kk, -1] : null) : [kk, 1]; renderReader(); const again = $(`#factTable th[data-k="${kk}"] button`); if (again) again.focus({ preventScroll: true }); };
  document.querySelectorAll("#bioStrip button").forEach(btn => btn.classList.toggle("on", +btn.dataset.b === state.bio));
}
function scrollFactsTo(si) {
  const row = document.querySelector(`#factTable tr[data-s="${si}"]`);
  const box = $(".facts-scroll");
  if (row && box) box.scrollTop = row.offsetTop - 40;
}

/* ------------------------------------------------------------ gain chart */
const GAIN_SIGS = ["probe", "stack", "ptrue", "pop", "verifier"];
const CURVES = Object.fromEntries(GAIN_SIGS.map(k => [k, gainCurve(claims, SIG[k].key)]));
const POOLED = { probe: NUM.probe_auroc, ptrue: NUM.ptrue_auroc, verifier: NUM.verifier_auroc, stack: NUM.stack_test_auroc, pop: NUM.pageviews_auroc };
function drawGain() {
  const el = $("#gainChart");
  const m = { l: 44, r: 14, t: 24, b: 40 };
  const F = frame(el, Math.min(390, Math.max(310, el.clientWidth * 0.75)), m);
  const x = d3.scaleLinear().domain([0, 1]).range([0, F.iw]), y = d3.scaleLinear().domain([0, 1]).range([F.ih, 0]);
  F.g.append("g").attr("class", "axis").attr("transform", `translate(0,${F.ih})`).call(d3.axisBottom(x).ticks(5).tickFormat(d3.format(".0%")));
  F.g.append("g").attr("class", "axis").call(d3.axisLeft(y).ticks(5).tickFormat(d3.format(".0%")));
  F.g.append("text").attr("class", "lbl").attr("x", F.iw).attr("y", F.ih + 34).attr("text-anchor", "end").text("share of claims flagged →");
  F.g.append("text").attr("class", "lbl").attr("x", -40).attr("y", -12).text("↑ share of incorrect claims caught");
  F.g.append("line").attr("x1", x(0)).attr("y1", y(0)).attr("x2", x(1)).attr("y2", y(1)).attr("class", "gridline");
  const line = d3.line().x(d => x(d[0])).y(d => y(d[1]));
  GAIN_SIGS.slice().reverse().forEach(k => {
    F.g.append("path").attr("d", line(CURVES[k])).attr("fill", "none").style("stroke", SIG[k].color)
      .attr("stroke-width", k === "probe" ? 2.6 : k === state.sig ? 2.4 : 1.7).attr("stroke-dasharray", SIG[k].dash ? "5 4" : null).attr("opacity", k === "probe" || k === state.sig ? 1 : 0.8);
  });
  const xf = state.pctFlag / 100;
  F.g.append("line").attr("x1", x(xf)).attr("x2", x(xf)).attr("y1", 0).attr("y2", F.ih).style("stroke", "var(--flag)").attr("stroke-width", 2);
  F.g.append("text").attr("class", "lbl-ink").attr("x", x(xf) + 4).attr("y", F.ih - 6).text(`${state.pctFlag}% flagged`);
  GAIN_SIGS.forEach(k => { const v = interp(CURVES[k], xf); F.g.append("circle").attr("cx", x(xf)).attr("cy", y(v)).attr("r", 3.5).style("fill", SIG[k].color).style("stroke", "var(--panel)").attr("stroke-width", 1.5); });
  $("#gainLegend").innerHTML = GAIN_SIGS.map(k => `<span><span class="ln${SIG[k].dash ? " dash" : ""}" style="border-color:${SIG[k].color}"></span>${SIG[k].label}${SIG[k].explor ? " (exploratory)" : k === "pop" ? " (no model)" : ""} <span class="num muted">${f3(POOLED[k].value)} · ${pct(interp(CURVES[k], xf))}</span></span>`).join("");
}

/* ------------------------------------------------------------ within-bio dot plot */
function drawWithin() {
  const el = $("#withinChart");
  const rows = [["Probe", NUM.probe_within_test, "var(--c-probe)"], ["P(True)", NUM.ptrue_within_test, "var(--c-ptrue)"], ["Sentence position", NUM.position_within_test, "var(--muted)"], ["Llama-as-verifier", NUM.verifier_within_test, "var(--c-verifier)"]];
  const m = { l: 126, r: 48, t: 8, b: 30 }, rowH = 32;
  const F = frame(el, m.t + m.b + rows.length * rowH, m);
  const x = d3.scaleLinear().domain([0.45, 0.85]).range([0, F.iw]);
  F.g.append("g").attr("class", "axis").attr("transform", `translate(0,${rows.length * rowH})`).call(d3.axisBottom(x).ticks(4).tickFormat(d3.format(".2f")));
  F.g.append("line").attr("class", "gridline").attr("x1", x(0.5)).attr("x2", x(0.5)).attr("y1", 0).attr("y2", rows.length * rowH);
  rows.forEach(([lab, n, c], i) => {
    const yy = i * rowH + rowH / 2;
    F.g.append("text").attr("class", i === 0 ? "lbl-strong" : "lbl-ink").attr("x", -10).attr("y", yy + 4).attr("text-anchor", "end").text(lab);
    F.g.append("line").attr("x1", x(n.lo)).attr("x2", x(n.hi)).attr("y1", yy).attr("y2", yy).style("stroke", c).attr("stroke-width", 3).attr("opacity", 0.5).attr("stroke-linecap", "round");
    F.g.append("circle").attr("cx", x(n.value)).attr("cy", yy).attr("r", 5).style("fill", c).style("stroke", "var(--panel)").attr("stroke-width", 1.5);
    F.g.append("text").attr("class", "lbl-ink").attr("x", x(n.hi) + 6).attr("y", yy + 4).text(f3(n.value));
  });
}

/* ------------------------------------------------------------ per-biography strip */
function drawStrip() {
  const el = $("#bioStrip");
  const order = D.bios.map((b, i) => i).sort((a, b) => (BIO_AUC[b].p || 0) - (BIO_AUC[a].p || 0));
  el.innerHTML = order.map(i => {
    const A = BIO_AUC[i], X = v => (isFinite(v) ? v * 100 : null);
    const dot = (v, c, r) => X(v) == null ? "" : `<circle cx="${X(v)}%" cy="8" r="${r}" style="fill:${c}"></circle>`;
    const lo = Math.min(...[A.p, A.v].filter(isFinite)), hi = Math.max(...[A.p, A.v].filter(isFinite));
    return `<button data-b="${i}" class="${i === state.bio ? "on" : ""}"><span class="nm">${esc(D.bios[i].name)}</span>` +
      `<svg aria-hidden="true"><line x1="50%" x2="50%" y1="1" y2="15" class="gridline"></line>${isFinite(lo) ? `<line x1="${lo * 100}%" x2="${hi * 100}%" y1="8" y2="8" style="stroke:var(--rule)" stroke-width="3"></line>` : ""}${dot(A.v, "var(--c-verifier)", 4.5)}${dot(A.q, "var(--c-ptrue)", 4)}${dot(A.p, "var(--c-probe)", 4.5)}</svg>` +
      `<span class="meta">${f2(A.p)} · ${A.nF} ✗</span></button>`;
  }).join("");
  el.onclick = e => { const b = e.target.closest("button"); if (!b) return; if (!on("#bioSel")) return; state.bio = +b.dataset.b; state.sel = null; $("#bioSel").value = state.bio; renderReader(); const rd = document.getElementById("reader"); if (rd) rd.scrollIntoView(); };
}

/* ------------------------------------------------------------ scatter (stack) */
function drawScatter() {
  const el = $("#scatter");
  const m = { l: 46, r: 12, t: 22, b: 40 };
  const F = frame(el, Math.min(410, Math.max(310, el.clientWidth * 0.8)), m);
  const x = d3.scaleLinear().domain(d3.extent(claims, c => c.pl)).nice().range([0, F.iw]);
  const y = d3.scaleLinear().domain(d3.extent(claims, c => c.ql)).nice().range([F.ih, 0]);
  F.g.append("g").attr("class", "axis").attr("transform", `translate(0,${F.ih})`).call(d3.axisBottom(x).ticks(6));
  F.g.append("g").attr("class", "axis").call(d3.axisLeft(y).ticks(6));
  F.g.append("text").attr("class", "lbl").attr("x", F.iw).attr("y", F.ih + 34).attr("text-anchor", "end").text("probe logit →");
  F.g.append("text").attr("class", "lbl").attr("x", -42).attr("y", -10).text("↑ P(True) logit difference");
  // lines of equal stack score: cp*x + ct*y = c
  const cp = NUM.stack_coef_p.value, ct = NUM.stack_coef_t.value;
  const [x0, x1] = x.domain(), [y0, y1] = y.domain();
  const cs = d3.extent([[x0, y0], [x0, y1], [x1, y0], [x1, y1]].map(([a, b]) => cp * a + ct * b));
  const clip = F.svg.append("defs").append("clipPath").attr("id", "scClip").append("rect").attr("width", F.iw).attr("height", F.ih);
  const gl = F.g.append("g").attr("clip-path", "url(#scClip)");
  d3.range(1, 8).map(i => cs[0] + (cs[1] - cs[0]) * i / 8).forEach(c => {
    gl.append("line").attr("x1", x(x0)).attr("y1", y((c - cp * x0) / ct)).attr("x2", x(x1)).attr("y2", y((c - cp * x1) / ct))
      .style("stroke", "var(--c-stack)").attr("stroke-dasharray", "4 4").attr("opacity", 0.45);
  });
  const pts = claims.slice().sort((a, b) => b.y - a.y);
  gl.selectAll("circle").data(pts).join("circle").attr("cx", c => x(c.pl)).attr("cy", c => y(c.ql)).attr("r", 2.6)
    .style("fill", c => c.y ? "none" : "var(--ink)").style("stroke", c => c.y ? "var(--muted)" : "none").attr("stroke-width", 0.9).attr("opacity", c => c.y ? 0.5 : 0.8);
  const tip = tipFor(el);
  F.svg.on("mousemove", ev => {
    const [mx, my] = d3.pointer(ev, F.g.node());
    let best = null, bd = 64;
    for (const c of claims) { const dx = x(c.pl) - mx, dy = y(c.ql) - my, dd = dx * dx + dy * dy; if (dd < bd) { bd = dd; best = c; } }
    if (!best) return tip.hide();
    const [px, py] = d3.pointer(ev, el);
    tip.show(`<b>${esc(D.bios[best.bi].name)}</b><br>${esc(best.t)}<br>${best.y ? "✓ supported" : "✗ not supported"} · probe ${best.p.toFixed(2)} · P(True) ${best.q.toFixed(2)}`, px, py);
  }).on("mouseleave", () => tip.hide());
}

/* ------------------------------------------------------------ anatomy: tug of war */
function drawTug() {
  const el = $("#tugChart");
  const rows = [["Attention heads", NUM.head_pos.value, NUM.head_neg.value, NUM.head_net.value, NUM.share_heads.value],
                ["MLP neurons", NUM.neuron_pos.value, NUM.neuron_neg.value, NUM.neuron_net.value, NUM.share_neurons.value],
                ["Embedding", Math.max(D.mass.emb, 0), Math.min(D.mass.emb, 0), D.mass.emb, NUM.share_emb.value]];
  const narrow = el.clientWidth < 560;
  const m = { l: narrow ? 12 : 130, r: 16, t: 22, b: 30 }, rowH = narrow ? 52 : 40;
  const F = frame(el, m.t + m.b + rows.length * rowH, m);
  const lim = Math.ceil(Math.max(NUM.neuron_pos.value, -NUM.neuron_neg.value));
  const x = d3.scaleLinear().domain([-lim, lim]).range([0, F.iw]);
  F.g.append("g").attr("class", "axis").attr("transform", `translate(0,${rows.length * rowH})`).call(d3.axisBottom(x).ticks(narrow ? 5 : 9));
  if (!narrow) F.g.append("line").attr("x1", x(0)).attr("x2", x(0)).attr("y1", -6).attr("y2", rows.length * rowH).style("stroke", "var(--ink)").attr("stroke-width", 1);
  const nf = v => Math.abs(v) < 0.001 ? v.toFixed(4) : v.toFixed(3);
  F.g.append("text").attr("class", "lbl").attr("x", narrow ? 0 : x(0) - 6).attr("y", -8).attr("text-anchor", narrow ? "start" : "end").text(narrow ? "← wrong way" : "← ranks incorrect claims higher");
  F.g.append("text").attr("class", "lbl").attr("x", narrow ? F.iw : x(0) + 6).attr("y", -8).attr("text-anchor", narrow ? "end" : "start").text(narrow ? "right way →" : "ranks correct claims higher →");
  rows.forEach(([lab, p, n, net, sh], i) => {
    const y0 = i * rowH + (narrow ? 20 : 8), bh = narrow ? 18 : 22;
    if (narrow) { F.g.append("line").attr("x1", x(0)).attr("x2", x(0)).attr("y1", y0 - 2).attr("y2", y0 + bh + 2).style("stroke", "var(--ink)").attr("stroke-width", 1);
                  F.g.append("text").attr("class", "lbl-ink halo").attr("x", 0).attr("y", y0 - 5).text(`${lab}: net ${nf(net)} (${pct(sh, sh < 0.01 ? 2 : 0)})`); }
    else { F.g.append("text").attr("class", "lbl-strong").attr("x", -12).attr("y", y0 + bh / 2 - 1).attr("text-anchor", "end").text(lab);
           F.g.append("text").attr("class", "lbl").attr("x", -12).attr("y", y0 + bh / 2 + 12).attr("text-anchor", "end").text(`net ${nf(net)} · ${pct(sh, sh < 0.01 ? 2 : 0)}`); }
    F.g.append("rect").attr("x", x(0)).attr("y", y0).attr("width", Math.max(0.5, x(p) - x(0))).attr("height", bh).style("fill", "var(--pos)").attr("opacity", 0.85);
    F.g.append("rect").attr("x", x(n)).attr("y", y0).attr("width", Math.max(0.5, x(0) - x(n))).attr("height", bh).style("fill", "var(--neg)").attr("opacity", 0.85);
    F.g.append("circle").attr("cx", x(net)).attr("cy", y0 + bh / 2).attr("r", 4.5).style("fill", "var(--ink)").style("stroke", "var(--panel)").attr("stroke-width", 2);
    if (!narrow && p > 2) F.g.append("text").attr("class", "lbl-ink").attr("x", x(p) - 6).attr("y", y0 + bh / 2 + 4).attr("text-anchor", "end").style("fill", "var(--panel)").text(`+${p.toFixed(2)}`);
    if (!narrow && -n > 2) F.g.append("text").attr("class", "lbl-ink").attr("x", x(n) + 6).attr("y", y0 + bh / 2 + 4).style("fill", "var(--panel)").text(`−${(-n).toFixed(2)}`);
  });
}

/* ------------------------------------------------------------ anatomy: head grid */
function drawHeads() {
  const el = $("#headGrid");
  const H = D.mass.heads, L = H.length, NH = H[0].length;
  const top = new Set(D.mass.top_heads.map(h => h.layer + ":" + h.head));
  const m = { l: 26, r: 4, t: 16, b: 4 };
  const w = Math.max(280, el.clientWidth || 500), cell = Math.floor((w - m.l - m.r) / NH);
  const F = frame(el, m.t + m.b + cell * L, m);
  const mx = d3.max(H.flat(), v => Math.abs(v));
  for (let l = 0; l < L; l++) {
    if (l % 2 === 0 || cell >= 14) F.g.append("text").attr("class", "lbl").attr("x", -5).attr("y", l * cell + cell * 0.72).attr("text-anchor", "end").style("font-size", Math.min(11, cell * 0.8) + "px").text(l);
    for (let h = 0; h < NH; h++) {
      const v = H[l][h], a = Math.round(100 * Math.sqrt(Math.abs(v) / mx));
      F.g.append("rect").attr("x", h * cell + 0.5).attr("y", l * cell + 0.5).attr("width", cell - 1).attr("height", cell - 1).attr("rx", 1.5)
        .attr("style", `fill: color-mix(in srgb, ${v >= 0 ? "var(--pos)" : "var(--neg)"} ${a}%, var(--glass))`).attr("data-l", l).attr("data-h", h);
      if (top.has(l + ":" + h)) F.g.append("rect").attr("x", h * cell - 0.5).attr("y", l * cell - 0.5).attr("width", cell + 1).attr("height", cell + 1).attr("rx", 2).attr("fill", "none").style("stroke", "var(--ink)").attr("stroke-width", 1.6);
    }
  }
  [0, 8, 16, 24, 31].forEach(h => F.g.append("text").attr("class", "lbl").attr("x", h * cell + cell / 2).attr("y", -5).attr("text-anchor", "middle").style("font-size", "10px").text(h));
  const tip = tipFor(el);
  const total = NUM.sep_total.value;
  F.svg.on("mousemove", ev => {
    const r = ev.target.closest && ev.target.closest("rect[data-l]");
    if (!r) return tip.hide();
    const l = +r.dataset.l, h = +r.dataset.h, v = H[l][h], [px, py] = d3.pointer(ev, el);
    tip.show(`Layer ${l}, head ${h}<br>contribution ${v >= 0 ? "+" : "−"}${Math.abs(v).toFixed(4)}<br>${(100 * v / total).toFixed(2)}% of the separation${top.has(l + ":" + h) ? "<br><b>top 10</b>" : ""}`, px, py);
  }).on("mouseleave", () => tip.hide());
}
function headRegions() {
  const rows = D.mass.top_heads, total = NUM.sep_total.value;
  $("#headRegions").innerHTML = `<thead><tr><th>Head</th><th>Share</th><th>Attention from the sentence</th></tr></thead><tbody>` + rows.map(h => {
    const parts = [["r-bos", h.mean_mass_bos, "start tokens"], ["r-prompt", h.mean_mass_prompt_rest, "prompt"], ["r-earlier", h.mean_mass_earlier_answer, "earlier sentences"], ["r-own", h.mean_mass_own_sentence, "the sentence"]];
    return `<tr><td class="n">L${h.layer} H${h.head}</td><td class="n">${(100 * h.d / total).toFixed(1)}%</td><td><div class="rbar" title="${parts.map(p => `${p[2]} ${(100 * p[1]).toFixed(0)}%`).join(", ")}">${parts.map(p => `<i class="${p[0]}" style="width:${(100 * p[1]).toFixed(1)}%"></i>`).join("")}</div></td></tr>`;
  }).join("") + "</tbody>";
}

/* ------------------------------------------------------------ anatomy: neuron field */
const FIELD = (() => {
  const bin = atob(D.mass.neuron_f32_b64), bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const v = new Float32Array(bytes.buffer);
  // colour strength = rank of |mass| among all neurons
  const order = new Uint32Array(v.length);
  for (let i = 0; i < v.length; i++) order[i] = i;
  order.sort((a, b) => Math.abs(v[a]) - Math.abs(v[b]));
  const rank = new Float32Array(v.length);
  for (let r = 0; r < order.length; r++) rank[order[r]] = (r + 1) / order.length;
  return { v, rank, L: D.mass.shape[0], W: D.mass.shape[1] };
})();
const GRID = D.mass.curve.map(r => r[0]);
let fieldIdx = GRID.indexOf(50);
function cssColor(name) {
  const probe = document.createElement("span");
  probe.style.color = `var(${name})`; probe.style.display = "none"; (document.querySelector("[data-fx]") || document.body).appendChild(probe);
  const c = getComputedStyle(probe).color; probe.remove();
  const mm = c.match(/[\d.]+/g) || [0, 0, 0];
  return [+mm[0], +mm[1], +mm[2]];
}
function setupField() {
  const box = $("#field");
  box.innerHTML = "";
  for (let l = 0; l < FIELD.L; l++) box.insertAdjacentHTML("beforeend", `<figure><canvas width="128" height="112" aria-label="Layer ${l} neurons"></canvas><figcaption><span>L${l}</span><span class="lit" data-l="${l}"></span></figcaption></figure>`);
  const r = $("#fieldN");
  r.max = GRID.length - 1; r.value = fieldIdx;
  r.addEventListener("input", () => { fieldIdx = +r.value; paintField(); if (hasD3) drawConc(); });
}
function paintField() {
  const n = GRID[fieldIdx], share = D.mass.curve[fieldIdx][1], thr = D.mass.thresholds[fieldIdx];
  const shareTxt = share < 0.1 ? pct(share, 2) : pct(share, 1);
  $("#fieldNOut").textContent = fmtInt(n) + (n === 1 ? " neuron" : " neurons");
  $("#fieldShareOut").textContent = shareTxt;
  $("#fieldN").setAttribute("aria-valuetext", `top ${fmtInt(n)} neurons, holding ${shareTxt} of the positive neuron mass`);
  const bg = cssColor("--field-bg"), P = cssColor("--pos"), N = cssColor("--neg"), lit = cssColor("--flag");
  const canv = document.querySelectorAll("#field canvas");
  const r = n <= 300 ? 2 : n <= 2000 ? 1 : 0;  // few lit neurons: draw each as a block (ringed when very few) so it can be seen
  for (let l = 0; l < FIELD.L; l++) {
    const ctx = canv[l].getContext("2d"), img = ctx.createImageData(128, 112), d = img.data;
    const on = [];
    for (let i = 0; i < FIELD.W; i++) {
      const j = l * FIELD.W + i, v = FIELD.v[j];
      if (v > 0 && v >= thr) on.push(i);
      const p = FIELD.rank[j], t = 0.1 + 0.85 * p * p, c = v >= 0 ? P : N, o = i * 4;
      d[o] = bg[0] + (c[0] - bg[0]) * t; d[o + 1] = bg[1] + (c[1] - bg[1]) * t; d[o + 2] = bg[2] + (c[2] - bg[2]) * t; d[o + 3] = 255;
    }
    for (const i of on) {
      const cx = i % 128, cy = Math.floor(i / 128);
      for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
        const xx = cx + dx, yy = cy + dy; if (xx < 0 || yy < 0 || xx >= 128 || yy >= 112) continue;
        const ring = r === 2 && (Math.abs(dx) === 2 || Math.abs(dy) === 2), c = ring ? bg : lit, o = (yy * 128 + xx) * 4;
        d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2];
      }
    }
    ctx.putImageData(img, 0, 0);
    const lab = document.querySelector(`#field .lit[data-l="${l}"]`), nl = D.mass.lit_per_layer[fieldIdx][l];
    if (nl !== on.length) console.warn("field: lit count differs from the build", l, nl, on.length);
    lab.textContent = nl ? fmtInt(nl) + " lit" : "";
  }
}
function drawConc() {
  const el = $("#concChart");
  const m = { l: 40, r: 10, t: 12, b: 36 };
  const F = frame(el, 220, m);
  const x = d3.scaleLog().domain([1, GRID[GRID.length - 1]]).range([0, F.iw]), y = d3.scaleLinear().domain([0, 1]).range([F.ih, 0]);
  F.g.append("g").attr("class", "axis").attr("transform", `translate(0,${F.ih})`).call(d3.axisBottom(x).tickValues([1, 10, 100, 1000, 10000, 100000]).tickFormat(d3.format("~s")));
  F.g.append("g").attr("class", "axis").call(d3.axisLeft(y).ticks(4).tickFormat(d3.format(".0%")));
  F.g.append("text").attr("class", "lbl").attr("x", F.iw).attr("y", F.ih + 30).attr("text-anchor", "end").text("top neurons (log) →");
  F.g.append("path").attr("d", d3.line().x(d => x(d[0])).y(d => y(d[1]))(D.mass.curve)).attr("fill", "none").style("stroke", "var(--pos)").attr("stroke-width", 2);
  const [n, s] = D.mass.curve[fieldIdx];
  F.g.append("line").attr("x1", x(n)).attr("x2", x(n)).attr("y1", y(s)).attr("y2", F.ih).style("stroke", "var(--flag)").attr("stroke-width", 1.5);
  F.g.append("circle").attr("cx", x(n)).attr("cy", y(s)).attr("r", 5).style("fill", "var(--flag)").style("stroke", "var(--panel)").attr("stroke-width", 2);
}

/* ------------------------------------------------------------ knockouts */
let doseMode = "cost";
function drawDose() {
  const el = $("#doseChart");
  const m = { l: 52, r: 18, t: 16, b: 42 };
  const F = frame(el, Math.min(420, Math.max(300, el.clientWidth * 0.5)), m);
  const base = NUM.A_base.value;
  const series = [
    { k: "neurons", top: true, lab: "Top neurons", c: "var(--pos)" },
    { k: "neurons", top: false, lab: "Random neurons", c: "var(--pos)" },
    { k: "heads", top: true, lab: "Top heads", c: "var(--neg)" },
    { k: "heads", top: false, lab: "Random heads", c: "var(--neg)" }
  ];
  const val = (r, top) => doseMode === "cost" ? r[top ? "A_base_minus_A_top" : "A_base_minus_A_rand"] : r[top ? "A_top" : "A_rand"];
  const x = d3.scaleLog().domain([7, 30000]).range([0, F.iw]);
  const y = doseMode === "cost" ? d3.scaleLinear().domain([-0.085, 0.32]).range([F.ih, 0]) : d3.scaleLinear().domain([0.3, 0.72]).range([F.ih, 0]);
  const narrow = F.iw < 420;
  F.g.append("g").attr("class", "axis").attr("transform", `translate(0,${F.ih})`).call(d3.axisBottom(x).tickValues(narrow ? [10, 200, 5000] : [10, 50, 200, 1000, 5000, 20000]).tickFormat(d3.format(",")));
  F.g.append("g").attr("class", "axis").call(d3.axisLeft(y).ticks(6).tickFormat(d3.format(".2f")));
  F.g.append("text").attr("class", "lbl").attr("x", F.iw).attr("y", F.ih + 34).attr("text-anchor", "end").text("components knocked out (log) →");
  F.g.append("text").attr("class", "lbl").attr("x", 4).attr("y", -4).text(doseMode === "cost" ? "within-biography AUROC lost" : "within-biography AUROC left");
  const zeroY = doseMode === "cost" ? 0 : base, chanceY = doseMode === "cost" ? base - 0.5 : 0.5;
  F.g.append("line").attr("x1", 0).attr("x2", F.iw).attr("y1", y(zeroY)).attr("y2", y(zeroY)).style("stroke", "var(--ink)").attr("opacity", 0.5);
  F.g.append("text").attr("class", "lbl").attr("x", 4).attr("y", y(zeroY) + (doseMode === "cost" ? 14 : -6)).text(doseMode === "cost" ? "no loss" : `no knockout (${f3(base)})`);
  F.g.append("line").attr("x1", 0).attr("x2", F.iw).attr("y1", y(chanceY)).attr("y2", y(chanceY)).style("stroke", "var(--muted)").attr("stroke-dasharray", "6 4");
  F.g.append("text").attr("class", "lbl").attr("x", 4).attr("y", y(chanceY) + (doseMode === "cost" ? -5 : 13)).text("chance (AUROC 0.5)");
  // preregistered 200-neuron bar
  if (doseMode === "cost") {
    const thr = NUM.necessity_threshold.value, px = x(200), py = y(NUM.cost_car200.value), ty = y(-0.045);
    F.g.append("circle").attr("cx", px).attr("cy", py).attr("r", 9).attr("fill", "none").style("stroke", "var(--ink)").attr("stroke-width", 1.2);
    if (!narrow) F.g.append("line").attr("x1", px).attr("x2", px).attr("y1", py + 9).attr("y2", ty - 14).style("stroke", "var(--muted)").attr("stroke-width", 1);
    const tx = narrow ? F.iw : px, anchor = narrow ? "end" : "middle";
    F.g.append("text").attr("class", "lbl-ink halo").attr("x", tx).attr("y", ty).attr("text-anchor", anchor).text(narrow ? "ringed: preregistered test" : "preregistered test, 200 neurons");
    F.g.append("text").attr("class", "lbl halo").attr("x", tx).attr("y", ty + 14).attr("text-anchor", anchor).text(narrow ? `top − random ${f3(NUM.necessity_N.value)}, bar ${thr.toFixed(2)}` : `5 random sets: top − random ${f3(NUM.necessity_N.value)}, bar ${thr.toFixed(2)}`);
  }
  const tip = tipFor(el);
  series.forEach(s => {
    const rows = D.dose.filter(r => r.type === s.k).sort((a, b) => a.n - b.n);
    const pts = rows.map(r => ({ n: r.n, v: val(r, s.top), r }));
    F.g.append("path").attr("d", d3.line().x(p => x(p.n)).y(p => y(p.v.point))(pts)).attr("fill", "none").style("stroke", s.c).attr("stroke-width", s.top ? 2.4 : 1.6).attr("stroke-dasharray", s.top ? null : "5 4").attr("opacity", s.top ? 1 : 0.75);
    pts.forEach(p => {
      F.g.append("line").attr("x1", x(p.n)).attr("x2", x(p.n)).attr("y1", y(p.v.ci_low)).attr("y2", y(p.v.ci_high)).style("stroke", s.c).attr("stroke-width", 2).attr("opacity", 0.45);
      F.g.append("circle").attr("cx", x(p.n)).attr("cy", y(p.v.point)).attr("r", s.top ? 5 : 4).style("fill", s.top ? s.c : "var(--panel)").style("stroke", s.c).attr("stroke-width", 1.8)
        .on("mouseenter", ev => { const [px, py] = d3.pointer(ev, el); tip.show(`<b>${s.lab}, ${fmtInt(p.n)}</b><br>AUROC left ${f3(p.r[s.top ? "A_top" : "A_rand"].point)}<br>lost ${f3(p.r[s.top ? "A_base_minus_A_top" : "A_base_minus_A_rand"].point)} [${f3(p.r[s.top ? "A_base_minus_A_top" : "A_base_minus_A_rand"].ci_low)}, ${f3(p.r[s.top ? "A_base_minus_A_top" : "A_base_minus_A_rand"].ci_high)}]${s.top ? `<br>top − random ${f3(p.r.N.point)}` : "<br>mean of 3 random sets"}`, px, py); })
        .on("mouseleave", () => tip.hide());
    });
  });
  $("#doseLegend").innerHTML = series.map(s => `<span><span class="ln${s.top ? "" : " dash"}" style="border-color:${s.c}"></span>${s.lab}</span>`).join("") + `<span class="muted mono" style="font-size:.75rem">hover a point, or open the table below</span>`;
}
function doseTable() {
  const ci = o => `${f3(o.point)} [${f3(o.ci_low)}, ${f3(o.ci_high)}]`;
  const rows = D.dose.slice().sort((a, b) => (a.type > b.type ? -1 : a.type < b.type ? 1 : a.n - b.n));
  $("#doseTable").innerHTML = `<thead><tr><th>Set</th><th>AUROC left, top</th><th>AUROC left, random (3 sets)</th><th>Lost, top</th><th>Lost, random</th><th>Top − random</th></tr></thead><tbody>` +
    rows.map(r => `<tr><td class="n">${fmtInt(r.n)} ${r.type}</td><td class="n">${ci(r.A_top)}</td><td class="n">${ci(r.A_rand)}</td><td class="n">${ci(r.A_base_minus_A_top)}</td><td class="n">${ci(r.A_base_minus_A_rand)}</td><td class="n">${ci(r.N)}</td></tr>`).join("") + "</tbody>";
}

/* ------------------------------------------------------------ neuron browser */
// The public build leaves out which neurons were carriers, so the packet can still be rated blind.
const PUBLIC = !!D.public;
// build_explorer.py --embed-out writes these two sentences into the embedded markup too
const PUBLIC_KEY_NOTE = "This version leaves out which neurons were carriers, so the packet can still be rated blind.";
const PUBLIC_RO_NOTE = "This version leaves the per-neuron readout out.";
const NB = { role: "all", sort: PUBLIC ? "id" : "absd", cur: null, blind: false, guesses: {} };
const byId = Object.fromEntries(D.neurons.map(n => [n.id, n]));
function neuronList() {
  let L = D.neurons.filter(n => NB.role === "all" || n.role === NB.role);
  if (NB.sort === "absd" && !NB.blind) L.sort((a, b) => Math.abs(b.d) - Math.abs(a.d));
  else if (NB.sort === "rho") L.sort((a, b) => b.rho - a.rho);
  else L.sort((a, b) => a.id.localeCompare(b.id));
  return L;
}
// in blind mode a neuron stays hidden until it or its partner is guessed (the pairing gives the partner's role away)
const isHidden = n => PUBLIC || (NB.blind && !(n.id in NB.guesses) && !(n.match in NB.guesses));
function roleBadge(n) {
  if (PUBLIC) return "";
  if (isHidden(n)) return `<span class="role hidden">?</span>`;
  return `<span class="role ${n.role}">${n.role === "carrier" ? "carrier" : "random"}</span>`;
}
function renderNList() {
  const L = neuronList();
  if (!NB.cur || !L.some(n => n.id === NB.cur)) NB.cur = L.length ? L[0].id : null;
  $("#nList").innerHTML = L.map(n => `<button role="option" aria-selected="${n.id === NB.cur}" tabindex="${n.id === NB.cur ? 0 : -1}" class="${n.id === NB.cur ? "on" : ""}" data-id="${n.id}"><span class="id">${n.id}</span><span class="d">${esc(n.desc)}</span>${roleBadge(n)}</button>`).join("");
}
function tokens(sent, vals, scale) {
  return sent.pc.map((pc, i) => {
    const v = vals[i], a = Math.round(60 * Math.min(1, Math.abs(v) / scale));
    return esc(pc[0]) + `<span class="tk ${v >= 0 ? "p" : "n"}" style="--a:${a}%" title="${v.toFixed(3)}">${esc(pc[1])}</span>`;
  }).join("") + esc(sent.tail || "");
}
function histSvg(h) {
  const W = 360, Hh = 96, pad = 14, bw = (W - 2 * pad) / h.c.length, top = Math.max(...h.c) || 1;
  let s = `<svg viewBox="0 0 ${W} ${Hh + 8}" role="img" aria-label="Histogram of pooled activation over 1,209 sentences" style="width:100%;height:auto;display:block">`;
  h.c.forEach((c, i) => { const hh = c / top * (Hh - 2 * pad); s += `<rect x="${(pad + i * bw).toFixed(1)}" y="${(Hh - pad - hh).toFixed(1)}" width="${(bw - 1).toFixed(1)}" height="${hh.toFixed(1)}" style="fill:var(--muted)" opacity="0.7"></rect>`; });
  if (h.lo < 0 && h.hi > 0) { const x0 = pad + (0 - h.lo) / (h.hi - h.lo) * (W - 2 * pad); s += `<line x1="${x0}" x2="${x0}" y1="${pad - 6}" y2="${Hh - pad}" style="stroke:var(--ink)" stroke-dasharray="2 2"></line><text x="${x0}" y="${pad - 8}" class="lbl" text-anchor="middle">0</text>`; }
  s += `<text x="${pad}" y="${Hh + 6}" class="lbl">${h.lo.toFixed(2)}</text><text x="${W - pad}" y="${Hh + 6}" class="lbl" text-anchor="end">${h.hi.toFixed(2)}</text></svg>`;
  return s;
}
function renderNDetail() {
  const n = byId[NB.cur];
  if (!n) { $("#nDetail").innerHTML = ""; return; }
  const hidden = isHidden(n);
  const all = n.top.concat(n.bot), scale = Math.max(...all.map(r => Math.max(...r.v.map(Math.abs)))) || 1;
  const srow = r => { const s = D.sentences[r.sid]; return `<tr><td class="n">${r.a.toFixed(3)}</td><td><span class="sub">${esc(s.subj)}</span>${tokens(s, r.v, scale)}</td>${hidden ? "" : `<td class="lb" title="claims in this sentence: supported / not supported">✓${s.nt} ✗${s.nf}</td>`}</tr>`; };
  const crow = (c, lo) => `<tr><td class="n">${c.v.toFixed(2)}</td><td class="ctx${lo ? " lo" : ""}">${esc(c.l)}<b>${esc(c.p)}</b>${esc(c.r)}</td></tr>`;
  const tailTxt = n.d >= 0 ? "net, ranks correct claims higher" : "net, ranks incorrect claims higher";
  const roTxt = n.ro_mixed ? "readout sign varies across folds" : n.ro >= 0 ? "higher activation raises the probe score" : "higher activation lowers the probe score";
  const facts = hidden ? `<span>simulation ρ <b>${n.rho.toFixed(2)}</b></span>`
    : `<span>layer <b>${n.layer}</b>, index <b>${n.index}</b></span><span>mass <b>${n.d >= 0 ? "+" : "−"}${Math.abs(n.d).toFixed(5)}</b> (${tailTxt})</span>${n.role === "carrier" ? `<span>rank <b>${n.rank}</b> of 50 in its tail</span>` : ""}<span><b>${roTxt}</b></span><span>simulation ρ <b>${n.rho.toFixed(2)}</b></span>`;
  const guess = PUBLIC ? "" : hidden ? `<div class="guess"><span>Carrier or matched random?</span><button class="btn" data-g="carrier">Carrier</button><button class="btn" data-g="random">Random</button></div>`
    : (NB.blind ? `<div class="guess"><span>${n.id in NB.guesses ? `You guessed <b>${NB.guesses[n.id]}</b>: ${NB.guesses[n.id] === n.role ? "right" : "wrong"}.` : `Revealed by its partner ${n.match}.`} It is a ${n.role === "carrier" ? "carrier" : "matched random neuron"}.</span></div>` : "");
  $("#nDetail").innerHTML = `
    <div class="nhead"><h3 tabindex="-1">${n.id}</h3>${roleBadge(n)}${hidden ? "" : `<button class="btn" data-goto="${n.match}">${n.role === "carrier" ? "its matched random neuron" : "its carrier"}: ${n.match} →</button>`}</div>
    <div class="kv">${facts}</div>
    ${guess}
    <blockquote class="desc">${esc(n.desc)}${n.desc_low ? `<span class="low">Low side: ${esc(n.desc_low)}</span>` : ""}</blockquote>
    <div class="kv"><span>fits the sentences <b>${n.coh}</b></span><span>fits web text <b>${n.fw}</b></span><span>category <b>${n.cat || "n/a"}</b></span><span>confidence <b>${n.conf}</b>/3</span><span>second rater: <b>${n.cat_b || (n.coh_b === "no" ? "not coherent" : "n/a")}</b></span></div>
    <div style="display:grid; gap:8px; min-width:0">
      <h3>Highest-activating biography sentences</h3>
      <div class="tablewrap"><table class="srows">${n.top.map(srow).join("")}</table></div>
      <h3>Lowest-activating</h3>
      <div class="tablewrap"><table class="srows">${n.bot.map(srow).join("")}</table></div>
      <p class="caption">Orange tokens are positive activation and blue negative, scaled to this neuron's largest token value (${scale.toFixed(2)}); hover a token for its value. Colour shows activation, not effect: ${PUBLIC ? "this public version leaves out each neuron's readout, so it does not say whether high activation raises or lowers the probe score" : hidden ? "whether high activation raises or lowers the probe score is shown once the neuron is revealed" : n.ro_mixed ? "this neuron's readout changes sign across folds, so the direction of its effect is not stable" : n.ro >= 0 ? "for this neuron, higher activation raises the probe score" : "for this neuron, higher activation lowers the probe score, so its lowest-activating sentences are the ones its readout favours"}. Left: the sentence average.${hidden ? "" : " Right: how many of the sentence's claims are supported and not."}</p>
    </div>
    <div class="cols" style="grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr))">
      <div style="min-width:0; display:grid; gap:6px; align-content:start">
        <h3>All 1,209 sentences</h3>
        ${histSvg(n.hist)}
        <p class="caption">Sentence-average activation. FineWeb sample, 5M tokens: mean ${n.fw_mean.toFixed(3)}, s.d. ${n.fw_std.toFixed(3)}.</p>
      </div>
      <div style="min-width:0; display:grid; gap:6px; align-content:start">
        <h3>Web text, highest tokens</h3>
        <table class="srows">${n.fw_top.map(c => crow(c, false)).join("")}</table>
      </div>
      <div style="min-width:0; display:grid; gap:6px; align-content:start">
        <h3>Web text, lowest tokens</h3>
        <table class="srows">${n.fw_bot.map(c => crow(c, true)).join("")}</table>
      </div>
    </div>`;
}
function guessScore() {
  const ids = Object.keys(NB.guesses);
  $("#guessScore").textContent = ids.length ? `${ids.filter(i => NB.guesses[i] === byId[i].role).length} of ${ids.length} right` : "";
}
function setupNeurons() {
  if (PUBLIC) {
    $("#roleSeg").closest(".ctl").hidden = true;
    $("#blind").closest(".ctl").hidden = true;
    const absd = $("#nSort").querySelector('option[value="absd"]');
    if (absd) absd.remove();
    $("#nSort").value = "id";
    $("#keyNote").textContent = PUBLIC_KEY_NOTE;
    $("#roNote").textContent = PUBLIC_RO_NOTE;
    $("#lbNote").hidden = true;
  }
  $("#roleSeg").addEventListener("click", e => { const b = e.target.closest("button"); if (!b) return; NB.role = b.dataset.r; $("#roleSeg").querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b)); renderNList(); renderNDetail(); });
  $("#nSort").addEventListener("change", e => { NB.sort = e.target.value; renderNList(); });
  $("#blind").addEventListener("change", e => {
    NB.blind = e.target.checked;
    if (NB.blind) { NB.cur = null; NB.role = "all"; $("#roleSeg").querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x.dataset.r === "all")); if (NB.sort === "absd") { NB.sort = "id"; $("#nSort").value = "id"; } }
    $("#roleSeg").querySelectorAll("button").forEach(x => { x.disabled = NB.blind; });
    { const absd = $("#nSort").querySelector('option[value="absd"]'); if (absd) absd.disabled = NB.blind; }
    renderNList(); renderNDetail(); guessScore();
  });
  const focusCur = () => { const b = document.querySelector(`#nList button[data-id="${NB.cur}"]`); if (b) { b.focus({ preventScroll: true }); b.scrollIntoView({ block: "nearest" }); } };
  $("#nList").addEventListener("click", e => { const b = e.target.closest("button[data-id]"); if (!b) return; NB.cur = b.dataset.id; renderNList(); renderNDetail(); focusCur(); });
  $("#nList").addEventListener("keydown", e => {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
    e.preventDefault();
    const L = neuronList(), i = L.findIndex(n => n.id === NB.cur);
    const j = e.key === "Home" ? 0 : e.key === "End" ? L.length - 1 : Math.max(0, Math.min(L.length - 1, i + (e.key === "ArrowDown" ? 1 : -1)));
    NB.cur = L[j].id; renderNList(); renderNDetail(); focusCur();
  });
  $("#nDetail").addEventListener("click", e => {
    const g = e.target.closest("button[data-g]");
    if (g) { NB.guesses[NB.cur] = g.dataset.g; renderNList(); renderNDetail(); guessScore(); const h = $("#nDetail h3"); if (h) h.focus({ preventScroll: true }); return; }
    const go = e.target.closest("button[data-goto]");
    if (go) { const id = go.dataset.goto; if (NB.role !== "all" && byId[id].role !== NB.role) { NB.role = "all"; $("#roleSeg").querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x.dataset.r === "all")); } NB.cur = id; renderNList(); renderNDetail(); focusCur(); }
  });
}

/* ------------------------------------------------------------ provenance */
function provTable() {
  const rows = Object.entries(NUM);
  const show = r => typeof r.value === "number" ? (Number.isInteger(r.value) ? fmtInt(r.value) : r.value.toPrecision(6)) + (r.lo != null ? ` [${r.lo.toPrecision(4)}, ${r.hi.toPrecision(4)}]` : "") : String(r.value);
  $("#provTable").innerHTML = `<thead><tr><th>Name</th><th>Value</th><th>Paper prints</th><th>File</th><th>Key</th></tr></thead><tbody>` +
    rows.map(([k, r]) => `<tr><td>${esc(k)}</td><td>${esc(show(r))}</td><td>${r.paper != null ? esc(r.paper) : ""}</td><td>${esc(r.src)}</td><td>${esc(r.path)}</td></tr>`).join("") + "</tbody>";
}

/* ------------------------------------------------------------ chapter highlight */
function setupNav() {
  const links = [...document.querySelectorAll(".chapters a")];
  const secs = links.map(a => document.querySelector(a.getAttribute("href")));
  const io = new IntersectionObserver(es => {
    es.forEach(e => { if (e.isIntersecting) links.forEach(a => a.classList.toggle("on", a.getAttribute("href") === "#" + e.target.id)); });
  }, { rootMargin: "-45% 0px -50% 0px" });
  secs.forEach(s => s && io.observe(s));
}

/* ------------------------------------------------------------ boot */
function themeChanged() { if (on("#field")) paintField(); }
if (on("#bioSel")) { setupReader(); renderReader(); }
if (on("#bioStrip")) drawStrip();
if (on("#headRegions")) headRegions();
if (on("#doseTable")) doseTable();
if (on("#field")) setupField();
if (on("#nList")) { setupNeurons(); renderNList(); renderNDetail(); }
if (on("#provTable")) provTable();
setupNav();
if (on("#field")) paintField();
if (hasD3) {
  const all = [["#scoreboard", drawScoreboard], ["#gainChart", drawGain], ["#withinChart", drawWithin], ["#scatter", drawScatter], ["#tugChart", drawTug], ["#headGrid", drawHeads], ["#concChart", drawConc], ["#doseChart", drawDose]];
  all.forEach(([sel, f]) => { if (!on(sel)) return; try { f(); } catch (err) { console.error(err); } watch($(sel), f); });
  if (on("#doseMode")) $("#doseMode").addEventListener("click", e => { const b = e.target.closest("button"); if (!b) return; doseMode = b.dataset.m; $("#doseMode").querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b)); drawDose(); });
} else {
  document.querySelectorAll(".chart").forEach(el => { el.innerHTML = '<p class="caption">This chart needs the d3 library, which did not load. The numbers are in the text and ' + (window.__FX_DATA__ ? 'the tables on this page.' : 'the Sources table.') + '</p>'; });
}
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", themeChanged);
new MutationObserver(themeChanged).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme", "class"] });
})();
};
