  // the page's panel markup must come from the same build as this script
  if (roots.some(function (r) { return r.getAttribute("data-fx-build") !== "c545644ee271"; })) { document.documentElement.classList.add("fx-failed"); return; }
  var here = (document.currentScript && document.currentScript.src) || location.href;
  var base = here.slice(0, here.lastIndexOf("/") + 1), started = false, io = null;
  function mark(c) { document.documentElement.classList.add(c); }
